operations.query:
mutation UpdateStoppedAgentRunModelConfig($input: UpdateStoppedAgentRunModelConfigInput!) {
  updateStoppedAgentRunModelConfig(input: $input) {
    success
    outcome
    message
    isActive
    editability {
      editable
      reason
      __typename
    }
    canonicalSelection {
      llmModelIdentifier
      llmConfig
      __typename
    }
    fieldErrors {
      path
      message
      __typename
    }
    __typename
  }
}
